from typing import Any


_CENT = Decimal("0.01")


def _decimal(value: Any) -> Decimal:
    """Convert legacy numeric values, treating missing and empty values as zero."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Decimal("0")
    return Decimal(str(value))


def _rounded_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def recompute(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list]:
    """Recompute one live, non-cancelled order and its live lines."""
    new_order = order.copy()
    new_lines = [line.copy() for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    total = Decimal("0")

    for new_line in new_lines:
        if new_line.get("DEL_FLG") == "Y":
            continue

        quantity = _decimal(new_line.get("QTY"))
        unit_price = _decimal(new_line.get("UNIT_PRC"))
        extension = _rounded_cents(quantity * unit_price)
        new_line["EXT_AMT"] = float(extension)
        total += extension

    discount_percent = _decimal(order.get("DISC_PCT"))
    discounted = _rounded_cents(
        total * (Decimal("100") - discount_percent) / Decimal("100")
    )

    incoming_total = _decimal(order.get("TOT_AMT"))
    new_order["TOT_AMT"] = float(discounted)

    audits = []
    if incoming_total != discounted:
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
